<template><section class="keyboard-preview" aria-label="快捷键键盘演示"><header><div><strong>{{entry?entry.title:'立体键盘演示'}}</strong><span v-if="entry"> · {{entry.platform}}</span><span v-else> · 悬停或聚焦卡片，查看按下的组合键</span></div><button v-if="entry&&entry.strokes.length>1" type="button" @click="next">下一组按键</button></header><p class="keyboard-status" aria-live="polite">{{entry?stroke.text:'尚未选择快捷键'}}<span v-if="entry&&entry.strokes.length>1"> · 第 {{step+1}} / {{entry.strokes.length}} 组（依次按下）</span></p><div class="keyboard-scroll" tabindex="0" aria-label="键盘布局，可横向滚动"><div class="keyboard-board" :class="{'keyboard-board-mac':isMac}"><div class="keyboard-main"><div v-for="(row,index) in rows" :key="index" class="keyboard-row"><span v-for="key in row" :key="key.id" class="keyboard-key" :class="{'is-pressed':stroke.ids.includes(key.id)}" :style="{flexGrow:key.width}" :data-key="key.id" :data-pressed="stroke.ids.includes(key.id)?'true':'false'" :aria-label="key.label+(stroke.ids.includes(key.id)?' 已按下':'')">{{key.label}}</span></div></div><div class="keyboard-navigation" aria-label="编辑导航键与方向键"><span v-for="key in navigation" :key="key.id" class="keyboard-key" :class="{'is-pressed':stroke.ids.includes(key.id)}" :style="{gridRow:key.row,gridColumn:key.column}" :data-key="key.id" :data-pressed="stroke.ids.includes(key.id)?'true':'false'" :aria-label="key.label+(stroke.ids.includes(key.id)?' 已按下':'')">{{key.label}}</span></div><div class="keyboard-numpad" aria-label="独立数字小键盘"><span v-for="key in numpad" :key="key.id" class="keyboard-key" :class="{'is-pressed':stroke.ids.includes(key.id),'numpad-wide':key.wide,'numpad-tall':key.tall}" :data-key="key.id" :data-pressed="stroke.ids.includes(key.id)?'true':'false'" :aria-label="'数字小键盘 '+key.label+(stroke.ids.includes(key.id)?' 已按下':'')">{{key.label}}</span></div></div></div><small v-if="stroke.unmapped.length"><span>未映射按键：{{stroke.unmapped.join('、')}}</span></small></section></template>
<script>
import {keyboardRows,keyboardNumpad,keyboardNavigation,previewStroke} from '../utils/shortcut-keyboard.mjs';
export default {name:'ShortcutKeyboard',props:{entry:{type:Object,default:null}},data:()=>({step:0,timer:null,motion:null,onMotion:null}),computed:{isMac(){return this.entry?.category==='macOS'||this.entry?.os==='macOS'||this.entry?.platform?.includes('macOS')||false;},rows(){return keyboardRows(this.isMac);},numpad(){return keyboardNumpad();},navigation(){return keyboardNavigation();},stroke(){return previewStroke(this.entry,this.step);}},watch:{entry(){this.step=0;this.restart();}},mounted(){this.motion=window.matchMedia('(prefers-reduced-motion: reduce)');this.onMotion=()=>this.restart();this.motion.addEventListener?.('change',this.onMotion);this.restart();},beforeUnmount(){this.stop();this.motion?.removeEventListener?.('change',this.onMotion);},methods:{next(){if(this.entry)this.step=(this.step+1)%this.entry.strokes.length;},stop(){if(this.timer!==null)clearInterval(this.timer);this.timer=null;},restart(){this.stop();if(this.entry?.strokes.length>1&&!this.motion?.matches)this.timer=setInterval(()=>this.next(),1300);}}};
</script>
<style scoped>.keyboard-preview{position:sticky;top:70px;z-index:8;background:var(--el-bg-color);border:1px solid var(--el-border-color);padding:12px;border-radius:7px;margin:14px 0 18px;box-shadow:0 5px 16px rgba(0,0,0,.08);}.keyboard-preview header{display:flex;gap:10px;justify-content:space-between;align-items:center;flex-wrap:wrap;font-size:12px;}.keyboard-preview header button{font:inherit;padding:4px 8px;color:inherit;background:var(--el-fill-color-blank);border:1px solid var(--el-border-color);border-radius:4px;cursor:pointer;}.keyboard-status{min-height:18px;margin:6px 0;color:var(--ui-accent);font:600 12px/1.5 Consolas,monospace;}.keyboard-scroll{overflow-x:auto;padding:5px 3px 8px;}.keyboard-board{display:flex;gap:12px;box-sizing:border-box;width:916px;min-width:916px;--keyboard-unit-height:29px;max-width:none;margin:auto;background:var(--el-fill-color-light);padding:9px;border:1px solid var(--el-border-color);border-radius:9px;}.keyboard-main{flex:0 0 610px;width:610px;}.keyboard-numpad{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));grid-auto-rows:var(--keyboard-unit-height);gap:5px;flex:0 0 144px;min-width:0;align-self:flex-start;margin-top:calc(var(--keyboard-unit-height) + 5px);}.keyboard-numpad .keyboard-key{height:auto;}.keyboard-numpad .numpad-wide{grid-column:span 2;}.keyboard-numpad .numpad-tall{grid-row:span 2;}.keyboard-navigation{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));grid-template-rows:repeat(6,var(--keyboard-unit-height));gap:5px;flex:0 0 118px;}.keyboard-row{display:flex;gap:5px;margin-bottom:5px;}.keyboard-row:last-child{margin-bottom:0;}.keyboard-key{display:flex;align-items:center;justify-content:center;flex-basis:0;min-width:0;box-sizing:border-box;height:var(--keyboard-unit-height);border:1px solid #b9c9bd;border-bottom:3px solid #91a697;border-radius:5px;color:#294c38;background:linear-gradient(#fff,#e4ece6);box-shadow:0 3px 0 #bdcbbf,inset 0 1px 0 white;font:600 10px/1 Consolas,monospace;user-select:none;}.keyboard-key.is-pressed{transform:translateY(3px);background:linear-gradient(#c2e5cc,#8fc5a0);color:#123c21;border-color:#487e59;box-shadow:0 0 0 1px #487e59,inset 0 2px 4px rgba(20,65,32,.18);}.keyboard-preview small{display:block;font-size:10px;color:var(--el-text-color-secondary);line-height:1.5;}@media(max-width:600px){.keyboard-preview{top:62px;padding:8px;}.keyboard-board{--keyboard-unit-height:25px;}.keyboard-row{margin-bottom:5px;}.keyboard-preview small{font-size:10px;}}
</style>
<style>body.dark .keyboard-preview .keyboard-key{background:linear-gradient(#294734,#122219);color:#d4ebdc;border-color:#45654f;border-bottom-color:#0c160f;box-shadow:0 3px 0 #050a07,inset 0 1px 0 rgba(157,198,168,.25);}body.dark .keyboard-preview .keyboard-key.is-pressed{background:linear-gradient(#2e6e43,#174529);color:#ecfff1;border-color:#a0cbae;box-shadow:0 0 0 1px #a0cbae,inset 0 2px 5px rgba(0,0,0,.25);}</style>
